{
  "schemaVersion": 1,
  "date": "2026-10-09",
  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-09-top-1"
      ],
      "question": "AIの判定APIを業務の分岐に組み込むとき、何を確認しますか。",
      "answer": "通信が成功しても、使える回答かを別に確認します。ただし、Decisions APIの実験では、HTTP 200でも回答型がrefusalとなる例がありました。predicateの確率は業務に合うしきい値で判定し、choiceは正解ラベルと比較します。確信度だけで自動処理を決めず、拒否や誤判定を有人確認へ回す経路を用意します。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-09-top-2"
      ],
      "question": "ブラウザ通話のノイズ抑制を導入するとき、効果をどう評価しますか。",
      "answer": "雑音の低下と、本人の声の聞き取りやすさを両方見ます。TwilioのRNNoise実験では、AudioProcessorを追加するとChrome標準の抑制を止めるため、比較条件をそろえる必要があります。打鍵音には効果がありましたが、周囲の会話は残り、本人の声も小さくなりました。雑音の種類を分け、実際の端末で聞き比べます。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-09-top-3"
      ],
      "question": "CIにセキュリティ検査を入れた場合、どこまで確認して合格としますか。",
      "answer": "設定の確認と、検査の完了を分けます。Continuumのdry-runは認証や連携を確かめますが、侵入テストは実行しません。ただし、記事ではCI/CDモードを有効にして起動できたものの、途中で中断しています。これを脆弱性ゼロとは扱わず、完了した結果と検出のしきい値を確認し、検査不能時に止める動作も試します。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-09-top-4"
      ],
      "question": "インフラコードをリファクタリングするとき、データを守るために何を見ますか。",
      "answer": "コードが同じ意味でも、リソースの同一性を確認します。CDKではConstructの階層を変えると論理IDが変わり、置換につながる場合があります。synthとdiffで変更を確認し、削除保護とRETAINは守る対象が違うと理解して設定します。プレビューのrefactorを使う場合も、差分を見ずに安全だとは判断しません。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-09-top-5"
      ],
      "question": "検索にリランキングを加えるとき、どの指標で効果を判断しますか。",
      "answer": "まず正解が候補に残るかを見て、次に順位の改善を見ます。記事ではEmbeddingGemma 2のRecall@10は97%で、上位10件を並べ替えるとHit@1は93%でした。ただし、費用は全件評価のスコアを再利用した見積もりです。精度だけでなく候補数と処理時間を確認し、実際の文書でも取りこぼしを調べます。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "articleIds": [
        "2026-10-09-top-1",
        "2026-10-09-top-3"
      ],
      "question": "HTTPの成功やdry-runの成功だけで、目的を達成したと言えますか。",
      "points": {
        "zh": "Decisions还需检查refusal；Continuum还需确认正式测试完成及结果，起动后中断不是零漏洞。",
        "ja": "Decisionsではrefusalを確認します。Continuumでは正式テストの完了と結果が必要で、中断を脆弱性ゼロと扱いません。"
      }
    },
    {
      "id": "review-02",
      "articleIds": [
        "2026-10-09-top-2",
        "2026-10-09-top-5"
      ],
      "question": "比較結果を使う前に、どの条件や算出方法を確かめますか。",
      "points": {
        "zh": "RNNoise对照是Chrome原生处理，单条件一次；RAG复用全量分数，费用与逐次耗时为估算。",
        "ja": "RNNoiseの対照はChrome標準処理で、各録音は1回です。RAGは全件スコアを再利用し、費用と逐次時間は算出値です。"
      }
    },
    {
      "id": "review-03",
      "articleIds": [
        "2026-10-09-top-4"
      ],
      "question": "CDKのコードを整理しても、実リソースが同じと限らないのはなぜですか。",
      "points": {
        "zh": "Construct路径会影响逻辑ID；应核实模板差异和替换，并区分不同删除保护的作用。",
        "ja": "Constructのパスが論理IDに影響するためです。差分と置換を見て、各保護の対象を区別します。"
      }
    }
  ]
}
